/* ---------- Existing cases: why we ask, early draft view, tool paths ---------- */
(function () {
  const C = MKDATA.CASES, why = {
    "1": ["Event films are one-shot, so the deliverable decides which studios are even relevant.", "Style narrows the list more than price does.", "Budget decides how big the crew can be.", "Timeline decides who can take the job."],
    "2": ["Positioning changes almost every later decision.", "The first audience decides where the early budget goes.", "An early offer gives people a reason to engage before the full launch.", "This decides how the first phase of the budget is used."],
    "3": ["The growth motion decides which channels make sense.", "I need to know what is built before I say what is missing.", "The goal decides what to fix first.", "Budget decides how much we can do at once."],
    "4": ["Your priority decides which channel to lean on.", "Search results take different amounts of time to show.", "Existing traffic decides how much SEO has to build on."],
    "gen": ["The outcome decides what a good test looks like.", "Timing decides how small the first step should be."]
  };
  Object.keys(why).forEach(k => { if (C[k]) why[k].forEach((w, i) => { if (C[k].chat[i]) C[k].chat[i].why = w; }); });

  const draft = {
    "1": "A studio that specializes in B2B event films is likely the best start. Your style and budget will sharpen which one.",
    "2": "Launch Reach through your existing TalentScout customers first. Positioning and the first offer will decide the details.",
    "3": "Settle your growth motion first, then positioning and a lead-capture path, before adding any channel.",
    "4": "Start with a small paid search test and begin SEO in parallel. Your horizon and traffic will sharpen the balance.",
    "fast": "Hire a studio experienced in short product videos."
  };
  Object.keys(draft).forEach(k => { C[k].draft = { answer: draft[k] }; });

  const tset = { c1a1: "t_video", cfa1: "t_video", c2a4: "t_gen", c2a5: "t_measure", c3a2: "t_list", c3a4: "t_gen", c4a3: "t_measure" };
  Object.keys(C).forEach(k => {
    const b = C[k].brief, acts = (b.actions || []).concat(b.priorities ? [].concat(b.priorities.now, b.priorities.next, b.priorities.later) : []);
    acts.forEach(a => { if (tset[a.id]) a.tset = tset[a.id]; });
    (C[k].variants || []).forEach(v => { (v.brief && v.brief.actions || []).forEach(a => { if (tset[a.id]) a.tset = tset[a.id]; }); (v.brief && v.brief.priorities ? [].concat(v.brief.priorities.now, v.brief.priorities.next || []) : []).forEach(a => { if (tset[a.id]) a.tset = tset[a.id]; }); });
  });
  /* "In-house" steps no longer have a button. A step with no path shows its hint. */
  const genOrig = MKDATA.genCase;
  MKDATA.genCase = function (request) {
    const g = genOrig(request);
    g.chat.forEach((q, i) => { q.why = why.gen[i]; });
    g.draft = { answer: "Start with a small, time-boxed test aimed at your main outcome." };
    g.brief.actions.forEach(a => { if (a.id === "cga2") a.tset = "t_measure"; });
    return g;
  };
})();

